import {initExperience} from './experience.js';
import {completionMarkup,initCompletion} from './completion.js';
import {initAccountNavigation} from './account-nav.js';
import {initShareTools} from './share-tools.js';

const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={arrow:'M7 17 17 7M7 7h10v10',run:'m7 20 4-7 3 3 3 4M4 13l4-3 4 2 2-7 4 3 3 1M17 3h.01',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c-5 5-5 13 0 18 5-5 5-13 0-18',medal:'m7 3 5 7 5-7M4 3h4l4 6 4-6h4l-5 9M9 12 4 3M17 16a5 5 0 1 1-10 0 5 5 0 0 1 10 0Zm-5-2v4m-2-2h4',check:'m5 12 4 4L19 6M21 12a9 9 0 1 1-9-9',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 6v6l4 2',search:'M16 16 21 21M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',calendar:'M5 5h14v16H5ZM8 2v6m8-6v6M5 10h14',link:'m9 15 6-6M8 16l-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m2 10a4 4 0 0 0 6 0l4-4a4 4 0 0 0-6-6l-1 1',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0Zm5 8a4 4 0 0 1 4 4v3M17 2a4 4 0 0 1 0 8',grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7Z',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8Zm0-6v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',image:'M3 3h18v18H3Zm0 14 6-6 5 5 3-3 4 4M16 7h.01',mail:'M3 5h18v14H3Zm0 0 9 8 9-8'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.arrow}"/></svg>`;
const badge=s=>`<span class="badge ${esc(s)}">${({pending:'Under review',open:'Submissions open',rejected:'Needs attention',closed:'Submissions closed'})[s]||esc(s)}</span>`;
const fmtDate=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'Flexible activity window';
const time=s=>{s=Math.round(s||0);return `${Math.floor(s/3600)?String(Math.floor(s/3600)).padStart(2,'0')+':':''}${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;};
const parseTime=s=>{const a=String(s).split(':');if(!/^(\d{1,2}:)?\d{1,2}:\d{2}$/.test(s)||Number(a.at(-1))>59||(a.length===3&&Number(a[1])>59))return NaN;return a.reduce((n,p)=>n*60+Number(p),0);};
const pace=(s,d)=>d?time(Math.round(s/d))+' /km':'—';
const ep=e=>'/events/'+encodeURIComponent(e.id);
const day=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Port_of_Spain'}).format(new Date());
const img=(src,alt,cls='',lazy=true)=>src?`<img src="${esc(src)}" alt="${esc(alt)}" class="${cls}" ${lazy?'loading="lazy"':''}>`:'';
const artSource='/assets/kyoto-medal.webp';
const link=(href,text,style='dark')=>`<a class="button ${style}" href="${href}">${text} <span aria-hidden="true">↗</span></a>`;
let site,events,route=location.pathname.replace(/\/$/,'')||'/',adminState,adminContent;
async function api(url,method='GET',data){const headers=data?{'Content-Type':'application/json'}:{};if(url.startsWith('/admin')){const code=sessionStorage.getItem('risenrun-admin-code');if(!code){location.replace('/login?role=admin');return new Promise(()=>{});}headers['X-Risenrun-Admin']=code;}const res=await fetch('/api'+url,{method,headers,body:data?JSON.stringify(data):undefined});const x=await res.json();if(res.status===401&&url.startsWith('/admin')){sessionStorage.removeItem('risenrun-admin-code');location.replace('/login?role=admin');return new Promise(()=>{});}if(!res.ok)throw new Error(x.error||'Unable to complete this action.');return x;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function logo(){return `<a class="logo" href="/" aria-label="Rise & Run TT home">${img('/assets/logo.webp','Rise & Run TT logo','',false)}<div class="wordmark">RISE & RUN<span>TRINIDAD & TOBAGO</span></div></a>`;}
function header(admin=false){return `${admin?'':`<div class="topline">Your run submission & results hub. &nbsp; <a href="/events">Find your event ↗</a></div>`}<header class="header"><div class="container header-inner">${logo()}<nav class="nav" id="main-nav" aria-label="Main navigation">${[['/events','Events'],['/how-it-works','How it works'],['/results','Results'],['/about','Our story']].map(([p,t])=>`<a class="${route.startsWith(p)?'active':''}" href="${p}">${t}</a>`).join('')}</nav><div class="header-actions"><a class="my-runs-link" href="/my-runs">My runs</a>${link('/events','Submit your run','dark')}<button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="main-nav">☰</button></div></div></header>`;}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-top"><div>${logo()}<p>${esc(site.tagline)}<br>Small steps. Memorable places.<br>A community that moves together.</p></div><div><h4>Your next step</h4><a href="/events">Find your event</a><a href="/my-runs">My runs & submissions</a><a href="/results">Official results</a><a href="/profile">Runner profile</a></div><div><h4>Here to help</h4><a href="/how-it-works">How it works</a><a href="/faq">Frequently asked questions</a><a href="mailto:${esc(site.email)}">${esc(site.email)}</a></div><div><h4>Find your people</h4><a href="${esc(site.instagram)}" target="_blank" rel="noreferrer">Instagram · @riserun.tt ↗</a><a href="/about">About Rise & Run TT</a><a href="/admin">Admin workspace</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ${esc(site.name)}. Every run has a story.</span><span>Made for movement. Made in T&T.</span></div></div></footer>`;}
function shell(content,title='Every run has a story'){document.title=title+' · Rise & Run TT';$('#app').innerHTML=header()+`<main id="main">${content}</main>`+footer();menu();initExperience();initAccountNavigation();initShareTools();}
function menu(){$('.menu-toggle')?.addEventListener('click',e=>{const b=e.currentTarget;const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));$('#main-nav').classList.toggle('open',open);});}
const crumbs=items=>`<div class="breadcrumbs"><a href="/">Home</a>${items.map(([t,h])=>`<span>/</span>${h?`<a href="${h}">${esc(t)}</a>`:`<span>${esc(t)}</span>`}`).join('')}</div>`;
function intro(kicker,title,text='',center=false){return `<section class="page-intro ${center?'center':''}"><div class="container"><span class="kicker">${kicker}</span><h1>${title}</h1>${text?`<p>${text}</p>`:''}</div></section>`;}
function empty(title,text,href='',button='Find your event'){return `<div class="empty">${icon('medal')}<h3>${title}</h3><p>${text}</p>${href?link(href,button):''}</div>`;}
function eventCard(e,resultsMode=false){return `<article class="event-card"><a href="${ep(e)}${resultsMode?'/results':''}" class="card-art" aria-label="${esc(e.name)} ${resultsMode?'results':'event details'}">${img(e.cover,e.name+' finisher medal')}${badge(e.status)}<span class="distance-label">${e.distance} KM · VIRTUAL</span></a><div class="card-body"><span class="kicker">${esc(e.series||e.location)}</span><h3><a href="${ep(e)}${resultsMode?'/results':''}">${esc(e.name)}</a></h3><p>${esc(e.subtitle||e.location)}</p><div class="card-bottom"><span>${resultsMode?`${e.finisherCount||0} verified finishers`:(e.startDate?fmtDate(e.startDate):'Your route. Your pace.')}</span><a class="text-link" href="${ep(e)}${resultsMode?'/results':''}">${resultsMode?'View results':'View event'} <span>↗</span></a></div></div></article>`;}
const steps=()=>`<div class="step-list">${[['01','Make the distance yours','Walk or run your event distance on a route you love.'],['02','Send us your finish','Upload a screenshot or paste your Strava activity link.'],['03','Make it official','We review your run. Your approved result joins the leaderboard.']].map(([n,t,p])=>`<div class="step-row"><span>${n}</span><div><h4>${t}</h4><p>${p}</p></div></div>`).join('')}</div>`;
function home(){const kyoto=events.find(e=>e.id==='escape-to-kyoto-virtual-5k')||events[0];shell(`<section class="hero"><div class="container hero-layout"><div class="hero-copy"><span class="kicker">Your effort. Your evidence. Your official result.</span><h1>You ran it.<br>Now make it <em>official.</em></h1><p>Choose your event, send us your run, and celebrate your finish. This is where your effort becomes part of the story.</p><div class="actions">${link('/events','Submit your run','')}${link('/my-runs','Track my submission','light-outline')}</div><div class="micro"><span></span>Run anywhere. Walk welcome. Every finish matters.</div><div class="hero-index">01 / THE EFFORT &nbsp; 02 / THE REVIEW &nbsp; 03 / YOUR FINISH</div></div><div class="hero-art"><div class="hero-label">${icon('medal')}<span>YOUR EVENT. YOUR FINISH.</span></div>${img(kyoto?.cover||artSource,kyoto?.name+' campaign medal','',false)}<div class="hero-caption"><div><small>${esc(kyoto?.series||'Rise & Run TT')} · ${esc(kyoto?.location||'Run anywhere')}</small><b>${esc(kyoto?.name||'Rise & Run TT')}</b></div><a href="${kyoto?ep(kyoto):'/events'}" aria-label="Explore the featured event">↗</a></div></div></div></section><div class="journey-strip"><div class="container journey-steps">${[['01','Make the distance','Your route. Your pace.'],['02','Submit your activity','Screenshot or Strava link.'],['03','Celebrate your finish','Reviewed by a real person.']].map(([n,t,p])=>`<div class="journey-step"><span class="journey-number">${n}</span><div><strong>${t}</strong><small>${p}</small></div>${icon('arrow')}</div>`).join('')}</div></div><section class="section"><div class="container"><div class="section-heading"><div><span class="kicker">Your event. Your next step.</span><h2>Find your event.<br>Send us your finish.</h2></div><a class="text-link" href="/events">View all events <span>↗</span></a></div><div class="card-grid">${events.slice(0,3).map(e=>eventCard(e)).join('')}</div></div></section><section class="section" style="background:#fff"><div class="container editorial"><div class="editorial-photo">${img('/assets/paris-campaign.webp','Escape to Paris medal and keepsake packaging from Rise & Run TT')}<div class="photo-note"><span>A little effort. Something to treasure.</span>${icon('medal')}</div></div><div><span class="kicker">More than the miles</span><h2>You do the run.<br>We celebrate<br><em>the finish.</em></h2><p>From your neighbourhood loop to your favourite coastal path, the adventure starts wherever you are. Completed your activity? Your next step is simple.</p>${steps()}<a class="text-link" href="/how-it-works">See how it works <span>↗</span></a></div></div></section><section class="story-band"><div class="copy"><span class="kicker">Travel the World · Destination 02</span><h2>A piece of Kyoto.<br>A part of<br><em>your story.</em></h2><p>Cherry blossoms, a beautifully detailed medal, and an air-mail keepsake. A small reminder of what happens when you keep showing up.</p>${link(events.some(e=>e.id==='escape-to-kyoto-virtual-5k')?'/events/escape-to-kyoto-virtual-5k':'/events','Explore the collection','dark')}</div>${img('/assets/kyoto-postcard.webp','Escape to Kyoto air-mail envelope and fan charm')}</section><section class="section"><div class="container"><div class="section-heading"><div><span class="kicker">From our corner of the world</span><h2>Rise together.</h2></div><a class="text-link" href="${esc(site.instagram)}" target="_blank" rel="noreferrer">@riserun.tt <span>↗</span></a></div><div class="social-grid">${[['travel-series','DdkIpj6uhvQ','Travel the World Series: Paris and Kyoto medals'],['paris-medal','DdFdLInBcL-','The Escape to Paris finisher medal'],['90s-medal','Dbt1aANRZVV','The 90s Babies finisher medal'],['kyoto-campaign','DdWWEZANwcT','Escape to Kyoto campaign']].map(([a,p,alt])=>`<a href="https://www.instagram.com/riserun.tt/reel/${p}/" target="_blank" rel="noreferrer">${img('/assets/'+a+'.webp',alt)}</a>`).join('')}</div></div></section>`);}
async function catalogue(resultsMode=false){let data=events;if(resultsMode){const r=await api('/results');data=events.map(e=>({...e,finisherCount:r.filter(x=>x.eventId===e.id).length}));}shell(intro(resultsMode?'Every finish, made official':'Your run submission hub',resultsMode?'The finish line.':'Find your event.<br>Make it <em>official.</em>',resultsMode?'Explore verified results from the Rise & Run TT collection.':'Open your event to upload your activity, check submission guidance, or view the results.',true)+`<section class="section" style="padding-top:12px"><div class="container"><div class="toolbar"><div class="search">${icon('search')}<input id="search-events" aria-label="Search events" type="search" placeholder="Search by event, destination or theme"></div><select id="sort-events" aria-label="Sort events"><option value="collection">Collection order</option><option value="az">Name A–Z</option><option value="date">Event date</option></select><div class="filter-chips">${[['all','All events'],['open','Accepting runs'],['closed','Closed submissions']].map(([v,t])=>`<button class="chip ${v==='all'?'selected':''}" data-filter="${v}" aria-pressed="${v==='all'}">${t}</button>`).join('')}</div></div><div id="event-catalogue" class="card-grid"></div><p class="catalog-footer" id="catalog-count"></p><div class="notice mt">Your next step: open your event, upload your activity, and follow its review in My runs.</div></div></section>`,resultsMode?'Results':'Events');let filter='all';const render=()=>{const q=$('#search-events').value.toLowerCase();let out=data.filter(e=>(filter==='all'||(filter==='closed'?['closed','completed'].includes(e.status):e.status===filter))&&[e.name,e.location,e.series].join(' ').toLowerCase().includes(q));if($('#sort-events').value==='az')out.sort((a,b)=>a.name.localeCompare(b.name));if($('#sort-events').value==='date')out.sort((a,b)=>(a.startDate||'9999').localeCompare(b.startDate||'9999'));$('#event-catalogue').innerHTML=out.length?out.map(e=>eventCard(e,resultsMode)).join(''):empty('No matching events','Try another destination or clear your search.');$('#catalog-count').textContent=`${out.length} ${out.length===1?'event':'events'} in the collection`;};$('#search-events').oninput=render;$('#sort-events').onchange=render;$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b);});render();});render();}
function eventDetail(e){const can=e.status==='open',future=e.startDate&&day()<e.startDate;const collection=e.collection||'Collection details will be announced by the organizer';shell(`<section class="event-hero"><div class="container">${crumbs([['Events','/events'],[e.name]])}<div class="event-layout"><div>${img(e.cover,e.name+' finisher medal','event-main-image',false)}<div class="gallery" aria-label="Event photo gallery">${[e.cover,...e.gallery].map((src,i)=>`<button class="${i===0?'selected':''}" data-gallery="${esc(src)}" aria-label="View event image ${i+1}">${img(src,e.name+' image '+(i+1))}</button>`).join('')}</div></div><div class="event-info"><span class="kicker">${esc(e.series)}</span>${badge(e.status)}<h1>${esc(e.name)}<br><span class="gold">Virtual ${e.distance}K</span></h1><p class="lead">${esc(e.subtitle)}</p><p>${esc(e.description)}</p><div class="event-facts"><div>${icon('run')}<strong>${e.distance} kilometres</strong><small>${e.activities.map(esc).join(' or ')}</small></div><div>${icon('globe')}<strong>Anywhere</strong><small>Your route. Your pace.</small></div><div>${icon('calendar')}<strong>${e.startDate?fmtDate(e.startDate).replace(' 2026',''):'Flexible window'}</strong><small>${e.endDate?'Until '+fmtDate(e.endDate):'See event guidance'}</small></div></div>${can?link(ep(e)+'/submit',future?'View submission requirements':'Submit my run','dark'):link(ep(e)+'/results','View event results','dark')}<a class="button outline" href="${ep(e)}/results">Explore the leaderboard <span>↗</span></a><p class="fine">Your activity is checked by the Rise & Run TT review team.${future?' Activities begin '+fmtDate(e.startDate)+'.':''}</p></div></div><nav class="event-tabs" aria-label="Event sections"><a href="#experience">The experience</a><a href="#medal">Your medal</a><a href="#submission-guide">Submission guide</a><a href="${ep(e)}/results">Results ↗</a></nav></div></section><section class="section" style="padding-top:0"><div class="container content-grid"><div><div id="experience"><span class="kicker">Every step is part of the story</span><h2>The world is big.<br>Your next step<br><em>can be small.</em></h2><p>${esc(e.description)}</p></div><h3 id="medal">A finish to hold onto.</h3><p>${esc(e.medalDescription)}</p><p><strong>Medal collection:</strong> ${esc(collection)}.</p>${e.pickupLocations.length?`<p><strong>Pickup locations:</strong> ${e.pickupLocations.map(esc).join(' · ')}. Follow the organizer’s announcement for confirmed dates and times.</p>`:''}<h3 id="submission-guide">Make your run official.</h3><ul><li>Complete ${e.distance} km within the event’s activity window.</li><li>Keep a screenshot showing distance, activity date and completion time.</li><li>Submit the screenshot or a Strava activity link for human review.</li><li>Follow your status in My runs. Approved results appear on the leaderboard.</li></ul><p>Accepted distance: ${e.minDistance}–${e.maxDistance} km.${e.deadline?' Submit by '+fmtDate(e.deadline)+', Trinidad & Tobago time.':''}</p></div><aside><div class="panel aside-card">${icon('medal')}<h3>The details that matter</h3><p><strong>Activity window</strong><br>${e.startDate?fmtDate(e.startDate)+' — '+fmtDate(e.endDate):'No fixed dates published. Contact the organizer if you are unsure whether your activity is eligible.'}</p><p><strong>Medal collection</strong><br>${esc(collection)}</p><p><strong>Need a hand?</strong><br><a href="mailto:${esc(site.email)}">${esc(site.email)}</a></p></div><div class="panel"><span class="kicker">Your organizer</span><h3>Rise & Run TT</h3><p>A community fitness initiative creating fun, themed virtual running events for people of all fitness levels.</p><a class="text-link mt" href="${esc(site.instagram)}" target="_blank" rel="noreferrer">Meet us on Instagram ↗</a></div></aside></div></section>`,e.name);$$('[data-gallery]').forEach(b=>b.onclick=()=>{$('.event-main-image').src=b.dataset.gallery;$$('[data-gallery]').forEach(x=>x.classList.toggle('selected',x===b));});}
const field=(label,name,type='text',value='',extra='')=>`<div><label for="${name}">${label}</label><input type="${type}" id="${name}" name="${name}" value="${esc(value)}" ${extra}></div>`;
const formError=(form,error)=>{let box=$('.form-error',form);if(!box){box=document.createElement('div');box.className='form-error';box.setAttribute('role','alert');form.prepend(box);}box.textContent=error.message||error;box.scrollIntoView({block:'nearest'});};
const getImage=file=>new Promise((resolve,reject)=>{if(!file)return reject(new Error('Choose an image.'));if(!['image/png','image/jpeg','image/webp'].includes(file.type))return reject(new Error('Choose a PNG, JPEG or WebP image.'));if(file.size>site.maxUploadMB*1024*1024)return reject(new Error(`Image must be smaller than ${site.maxUploadMB} MB.`));const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Unable to read the image.'));r.readAsDataURL(file);});
async function submitPage(e){const me=await api('/profile');const future=e.startDate&&day()<e.startDate;const closed=e.status!=='open'||(e.deadline&&day()>e.deadline&&!e.allowLate)||future;shell(intro('Your effort deserves a finish','Make it <em>official.</em>','Submit your activity for '+esc(e.name)+'. Our team will review it before your result is published.')+`<div class="container">${crumbs([['Events','/events'],[e.name,ep(e)],['Submit run']])}<div class="form-layout"><form id="submit-form" class="panel"><div class="form-steps"><span><b>1</b> Your proof</span><i></i><span><b>2</b> Run details</span><i></i><span><b>3</b> Submit for review</span></div>${closed?`<div class="notice">${future?'The activity window opens '+fmtDate(e.startDate)+'. Your completed activity can be submitted from then.':'This event is no longer accepting submissions.'}</div>`:''}<h3>How did you track your run?</h3><div class="method-picker">${e.methods.map((m,i)=>`<button type="button" class="method-button ${i===0?'selected':''}" data-method="${m}" aria-pressed="${i===0}">${icon(m==='screenshot'?'image':'link')}<span><strong>${m==='screenshot'?'Screenshot':'Strava activity'}</strong><small>${m==='screenshot'?'Upload your run proof':'Paste an activity link'}</small></span></button>`).join('')}</div><div id="proof-field"></div><div class="form-section"><h4>Your activity</h4><div class="form-grid">${field('Distance (km)','distance','number',e.distance,`required step="0.01" min="${e.minDistance}" max="${e.maxDistance}"`)}${field('Completion time (HH:MM:SS or MM:SS)','completion-time','text','','required placeholder="00:28:42" inputmode="numeric"')}<div><label for="activity">Activity type</label><select id="activity">${e.activities.map(a=>`<option>${a}</option>`).join('')}</select></div>${field('Activity date','activity-date','date','',`required max="${day()}" ${e.startDate?'min="'+e.startDate+'"':''}`)}</div><div class="pace-readout"><span>Your calculated average pace<br><small class="muted">Based on the distance and time above</small></span><strong id="pace-output">— /km</strong></div></div><div class="form-section"><h4>Your details</h4><div class="form-grid">${field('Display name · appears on results','display-name','text',me.displayName,'required maxlength="80"')}${field('Runner email · stays private','email','email',me.email,'required')}<div class="span-2"><label for="notes">Notes for the reviewer (optional)</label><textarea id="notes" maxlength="2000"></textarea></div></div><label class="check mt"><input type="checkbox" id="consent" required><span>I confirm this is my activity and I am a participant in this event. I agree to have my display name, time, distance and rank included in the official results after approval.</span></label></div><div class="form-error" role="alert"></div><button class="button dark wide mt" type="submit" ${closed?'disabled':''}>Submit my run for review <span>↗</span></button><p class="field-help center mt">Your screenshot and email are kept out of the public leaderboard.</p></form><aside class="form-aside"><div class="panel"><div class="mini-event">${img(e.cover,e.name+' medal')}<div><h3>${esc(e.name)}</h3><p>${e.distance} KM · ${e.activities.map(esc).join(' / ')}</p></div></div><div class="aside-details"><div class="notice">Your result becomes official after a human review. A Strava link is supporting evidence, not automatic verification.</div><h4>Before you submit</h4><p class="muted mt">Make sure your proof clearly shows your distance, completion time and activity date.</p><p class="small mt"><strong>Accepted distance</strong><br>${e.minDistance}–${e.maxDistance} km</p>${e.deadline?`<p class="small mt"><strong>Submission deadline</strong><br>${fmtDate(e.deadline)}</p>`:''}<a class="text-link mt" href="${ep(e)}">Back to event ↗</a></div></div></aside></div></div>`,'Submit your run');let method=e.methods[0],image='';const proof=()=>{$('#proof-field').innerHTML=method==='strava'?`${field('Strava activity URL','strava-url','url','','required placeholder="https://www.strava.com/activities/…"')}<p class="field-help">Make sure the activity can be viewed by the review team.</p>`:`<div class="dropzone" id="dropzone">${icon('upload')}<p><strong>Drop your run screenshot here</strong></p><p class="muted small">PNG, JPG or WebP · up to ${site.maxUploadMB} MB</p><input type="file" id="proof-image" accept="image/png,image/jpeg,image/webp" aria-label="Run screenshot"><img class="upload-preview hidden" id="proof-preview" alt="Your uploaded run screenshot"></div>`;if(method==='screenshot'){const read=async f=>{try{image=await getImage(f);$('#proof-preview').src=image;$('#proof-preview').classList.remove('hidden');$('.form-error').textContent='';}catch(err){image='';formError($('#submit-form'),err);}};$('#proof-image').onchange=x=>read(x.target.files[0]);const drop=$('#dropzone');drop.ondragover=x=>{x.preventDefault();drop.classList.add('drag');};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=x=>{x.preventDefault();drop.classList.remove('drag');read(x.dataTransfer.files[0]);};}};$$('[data-method]').forEach(b=>b.onclick=()=>{method=b.dataset.method;$$('[data-method]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b);});proof();});proof();const updatePace=()=>{const s=parseTime($('#completion-time').value);$('#pace-output').textContent=Number.isFinite(s)?pace(s,Number($('#distance').value)):'— /km';};$('#distance').oninput=updatePace;$('#completion-time').oninput=updatePace;$('#submit-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.currentTarget,b=$('button[type=submit]',form);b.disabled=true;b.classList.add('is-submitting');b.setAttribute('aria-busy','true');b.innerHTML='<span class="submit-spinner" aria-hidden="true"></span> Saving your run…';try{const seconds=parseTime($('#completion-time').value);if(!Number.isFinite(seconds))throw new Error('Enter time as MM:SS or HH:MM:SS.');if(method==='screenshot'&&!image)throw new Error('Choose your run screenshot.');const s=await api('/submissions','POST',{eventId:e.id,displayName:$('#display-name').value,email:$('#email').value,method,image,stravaUrl:$('#strava-url')?.value||'',distance:Number($('#distance').value),seconds,activity:$('#activity').value,activityDate:$('#activity-date').value,notes:$('#notes').value,consent:$('#consent').checked});location.href='/my-runs/'+s.id+'?submitted=1';}catch(err){formError(form,err);b.disabled=false;b.classList.remove('is-submitting');b.removeAttribute('aria-busy');b.innerHTML='Submit my run for review <span aria-hidden="true">↗</span>';}};}
const stat=(label,value)=>`<div class="stat-box"><small>${label}</small><strong>${value}</strong></div>`;
async function myRuns(){const me=await api('/me'),runs=me.submissions,approved=runs.filter(s=>s.status==='approved');shell(intro('Your running journey',me.profile?.displayName?`Keep rising,<br><em>${esc(me.profile.displayName)}.</em>`:'One run.<br>So many <em>possibilities.</em>','Your submitted activities, review updates and verified finishes, all in one place.')+`<section class="section" style="padding-top:10px"><div class="container"><div class="stat-grid">${stat('Runs submitted',runs.length)}${stat('Verified finishes',approved.length)}${stat('Awaiting review',runs.filter(s=>s.status==='pending').length)}${stat('Best verified 5K',approved.filter(s=>events.find(e=>e.id===s.eventId)?.distance===5).length?time(Math.min(...approved.filter(s=>events.find(e=>e.id===s.eventId)?.distance===5).map(s=>s.seconds))):'—')}</div><div class="section-heading"><h3>Your submissions</h3><a class="text-link" href="/profile">Edit runner profile ↗</a></div>${runs.length?`<div class="run-list">${runs.slice().reverse().map(s=>{const e=events.find(e=>e.id===s.eventId);return `<article class="run-card">${img(e?.cover,e?.name||'Event medal')}<div>${badge(s.status)}<h3>${esc(e?.name||s.eventId)}</h3><p>${fmtDate(s.activityDate)} · ${esc(s.method)}</p></div><div class="metrics">${time(s.seconds)}<p>${s.distance} km · ${pace(s.seconds,s.distance)}</p></div><div class="actions">${link('/my-runs/'+s.id,'View status','outline compact')}</div></article>`;}).join('')}</div>`:empty('Your journey starts with a run.','Once you submit your first activity, you can follow its review and see your finish here.','/events')}<div class="section-heading mt"><h3>Your medal collection</h3></div>${approved.length?`<div class="card-grid">${approved.map(s=>events.find(e=>e.id===s.eventId)).filter(Boolean).map(e=>eventCard(e,true)).join('')}</div>`:empty('A little space for big achievements.','Your medals will appear here when your event submissions are approved.')}<p class="small muted mt">Your run history is linked to this browser while account login is not enabled.</p></div></section>`,'My runs');}
async function runStatus(id){const s=await api('/submissions/'+id),e=events.find(e=>e.id===s.eventId);const r=s.status==='approved'?(await api('/results?event='+s.eventId)).find(x=>x.id===id):null;if(s.status==='pending'||s.status==='approved'){shell(completionMarkup({id:s.id,status:s.status,name:s.displayName,eventId:e?.id,eventName:e?.name||s.eventId,medal:e?.medal||e?.cover,eventDistance:e?.distance,distance:s.distance,time:time(s.seconds),pace:pace(s.seconds,s.distance),date:fmtDate(s.activityDate),activity:s.activity}),'Your finish moment');initCompletion();return;}const title={pending:'Run submitted.',approved:'You did it.',rejected:'One more step.'}[s.status];shell(intro('Your finish is taking shape',title,{pending:'Your activity is safely stored and waiting for a review.',approved:'Your run has been reviewed. This finish is officially yours.',rejected:'Your reviewer has asked for an updated submission.'}[s.status],true)+`<section class="section" style="padding-top:10px"><div class="container"><div class="result-card">${img(e?.medal,(e?.name||'Event')+' medal','result-medal')}<span class="kicker gold">${esc(e?.name||s.eventId)}</span>${badge(s.status)}<h2>${esc(s.displayName)}</h2><div class="result-time">${time(s.seconds)}</div><div class="result-meta"><div><b>${s.distance} km</b><small>DISTANCE</small></div><div><b>${pace(s.seconds,s.distance)}</b><small>PACE</small></div><div><b>${r?'#'+r.rank:'—'}</b><small>${r?'EVENT RANK':'RANK AFTER REVIEW'}</small></div></div></div><div class="status-timeline"><span class="done">✓ Run submitted</span><span class="${s.status!=='pending'?'done':''}">${s.status!=='pending'?'✓':'○'} Human review</span><span class="${r?'done':''}">${r?'✓':'○'} Official result</span></div>${s.reason?`<div class="panel" style="max-width:650px;margin:25px auto"><h3>Reviewer’s note</h3><p>${esc(s.reason)}</p>${e?.allowResubmit?link(ep(e)+'/submit','Submit another run','dark mt'):''}</div>`:''}<div class="actions" style="justify-content:center">${link('/my-runs','All my runs','outline')}${r?link('/results/'+s.id,'View & share result','dark'):link(e?ep(e)+'/results':'/results','Event results','outline')}</div></div></section>`,title);}
async function leaderboard(e){const all=await api('/results?event='+e.id);shell(intro('Verified efforts. Lasting results.',esc(e.name)+'<br><em>Official results.</em>',`${all.length} verified ${all.length===1?'finisher':'finishers'} · ${e.distance} km · ${esc(e.location)}`,true)+`<section class="section" style="padding-top:10px"><div class="container">${crumbs([['Events','/events'],[e.name,ep(e)],['Results']])}${all.length?`<div class="podium">${all.slice(0,3).map(r=>`<a class="podium-card" href="/results/${r.id}"><span class="rank">0${r.rank}</span><h3>${esc(r.displayName)}</h3><b>${time(r.seconds)}</b><small>${r.distance} km · ${pace(r.seconds,r.distance)}</small></a>`).join('')}</div><div class="toolbar"><div class="search">${icon('search')}<input id="runner-search" type="search" aria-label="Search runner" placeholder="Find a runner"></div><select id="result-sort" aria-label="Sort results"><option value="time">Fastest time</option><option value="pace">Fastest pace</option><option value="name">Runner name</option></select><button class="button outline compact" id="export-results">Export CSV</button></div><div id="results-table"></div><div class="pagination"><button class="button outline compact" id="prev-page">Previous</button><span id="page-count"></span><button class="button outline compact" id="next-page">Next</button></div>`:empty('The finish line is ready.','Approved runs will appear here. Submit your activity and let the review team make it official.',ep(e)+'/submit','Submit your run')}</div></section>`,e.name+' results');if(!all.length)return;let page=0;const render=()=>{let rows=all.filter(r=>r.displayName.toLowerCase().includes($('#runner-search').value.toLowerCase()));const sort=$('#result-sort').value;if(sort==='name')rows.sort((a,b)=>a.displayName.localeCompare(b.displayName));if(sort==='pace')rows.sort((a,b)=>a.seconds/a.distance-b.seconds/b.distance);const pages=Math.max(1,Math.ceil(rows.length/20));page=Math.min(page,pages-1);$('#results-table').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Rank</th><th>Runner</th><th>Finish time</th><th>Pace</th><th>Distance</th><th></th></tr></thead><tbody>${rows.slice(page*20,page*20+20).map(r=>`<tr><td>#${r.rank}</td><td>${esc(r.displayName)}</td><td><strong>${time(r.seconds)}</strong></td><td>${pace(r.seconds,r.distance)}</td><td>${r.distance} km</td><td><a class="table-link" href="/results/${r.id}">View result ↗</a></td></tr>`).join('')||'<tr><td colspan="6">No matching runners.</td></tr>'}</tbody></table></div>`;$('#page-count').textContent=`Page ${page+1} of ${pages} · ${rows.length} results`;$('#prev-page').disabled=page===0;$('#next-page').disabled=page===pages-1;};$('#runner-search').oninput=()=>{page=0;render();};$('#result-sort').onchange=render;$('#prev-page').onclick=()=>{page--;render();};$('#next-page').onclick=()=>{page++;render();};$('#export-results').onclick=()=>downloadCSV('results-'+e.id,[['Rank','Runner','Time','Pace','Distance'],...all.map(r=>[r.rank,r.displayName,time(r.seconds),pace(r.seconds,r.distance),r.distance])]);render();}
function downloadFile(name,content,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function downloadCSV(name,rows){const safe=x=>{let s=String(x??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};downloadFile(name+'.csv',rows.map(row=>row.map(safe).join(',')).join('\r\n'),'text/csv');}
async function resultPage(id){const all=await api('/results'),r=all.find(x=>x.id===id);if(!r)throw new Error('This result is not published. Only approved runs have a public result.');const e=events.find(x=>x.id===r.eventId),eventRows=all.filter(x=>x.eventId===r.eventId);r.rank=eventRows.findIndex(x=>x.id===id)+1;shell(intro('Official Rise & Run TT finisher','You showed up.<br>You <em>finished.</em>','Your effort, made official.',true)+`<section class="section" style="padding-top:5px"><div class="container"><div class="result-card" id="share-card">${img(e?.medal,(e?.name||'Event')+' medal','result-medal')}<span class="kicker gold">RISE & RUN TT · VERIFIED FINISH</span><h2>${esc(e?.name||r.eventId)}</h2><p>${esc(r.displayName)} · ${fmtDate(r.activityDate)}</p><div class="result-time">${time(r.seconds)}</div><div class="result-meta"><div><b>${r.distance} km</b><small>DISTANCE</small></div><div><b>${pace(r.seconds,r.distance)}</b><small>PACE</small></div><div><b>#${r.rank}</b><small>EVENT RANK</small></div></div></div><div class="actions mt" style="justify-content:center"><button class="button dark" id="share-result">Copy result link ↗</button><button class="button outline" id="print-result">Print result</button>${link(e?ep(e)+'/results':'/results','Event leaderboard','outline')}</div></div></section>`,'Official result');$('#share-result').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast('Result link copied. This local link works on this computer.');}catch{toast('Copy the result URL from your address bar.');}};$('#print-result').onclick=()=>window.print();}
async function profilePage(){const p=await api('/profile');shell(intro('The person behind the miles','Your runner<br><em>profile.</em>','Set the name you want to see beside your next finish.')+`<section class="section" style="padding-top:10px"><div class="container"><form class="panel" id="profile-form" style="max-width:740px"><div class="form-grid">${field('Full name','name','text',p.name,'required maxlength="120"')}${field('Public display name','displayName','text',p.displayName,'required maxlength="80"')}${field('Email','email','email',p.email,'required')}${field('Country','country','text',p.country,'required maxlength="100"')}</div><p class="field-help mt">Your email stays private. Your display name appears on results when you consent during submission. These details are saved for this browser.</p><div class="form-error" role="alert"></div><button class="button dark mt">Save profile</button></form></div></section>`,'Runner profile');$('#profile-form').onsubmit=async ev=>{ev.preventDefault();try{await api('/profile','PUT',Object.fromEntries(new FormData(ev.currentTarget)));toast('Runner profile saved.');}catch(err){formError(ev.currentTarget,err);}};}
const faqs=[['How does a virtual 5K work?','Complete the event distance on your own route during the event window. Use a fitness tracker to record distance, time and activity date. Submit proof here and our team will review your run.'],['What can I do on this website?','Submit your run, follow its review, and view official results. Open your event to find its activity window, proof requirements and medal collection details.'],['Can I walk instead of run?','Yes, when walking is an allowed activity for your event. Check the event page for its distance and accepted activity types.'],['What should my screenshot include?','Your completed distance, activity date and finish time must be readable. PNG, JPG and WebP images are accepted. The upload page shows the current size limit.'],['Does a Strava link automatically verify my run?','No. A Strava activity link is submitted as evidence for the review team. Make sure the activity is accessible to the reviewer.'],['When will my result appear?','Your result appears after the team approves your activity. You can check the review status in My runs. If anything needs attention, the reviewer’s reason is shown there.'],['How do I collect my medal?','Check your event page for the collection month and locations. Follow @riserun.tt for confirmed pickup dates and times.'],['Can I submit a correction?','If your activity is rejected and the event allows resubmissions, My runs will show a Submit another run button. Approved results can be corrected by the event admin.']];
function faqPage(){shell(intro('A little guidance goes a long way','Good questions.<br><em>Clear answers.</em>','Everything you need for a smooth finish.',true)+`<section class="section" style="padding-top:10px"><div class="container faq">${faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}<div class="notice mt">Still need a hand? <a href="mailto:${esc(site.email)}">Email ${esc(site.email)}</a>.</div></section>`,'Frequently asked questions');}
function howPage(){shell(intro('Your route from effort to official','Your finish,<br><em>in three steps.</em>','From a completed activity to a verified finish. Here’s what happens next.',true)+`<section class="section" style="padding-top:15px"><div class="container editorial"><div class="editorial-photo">${img('/assets/travel-series.webp','Paris and Kyoto medals in the Rise & Run TT collection')}</div><div>${steps()}<div class="notice">Check your event’s date window and distance before you run. Keep your activity proof until your result is approved.</div>${link('/events','Find your event','dark')}<p><a class="text-link" href="/faq">More questions? Visit the FAQ ↗</a></p></div></div></section>`,'How it works');}
function aboutPage(){shell(intro('Rooted in Trinidad & Tobago','Small island.<br><em>Endless possibilities.</em>','Encourage fitness & health anywhere.',true)+`<section class="section" style="padding-top:15px"><div class="container editorial"><div><span class="kicker">Meet Rise & Run TT</span><h2>Movement with<br>a little <em>imagination.</em></h2><p>Rise & Run TT is a community fitness initiative dedicated to creating fun, themed virtual running events that encourage people of all fitness levels to stay active.</p><p>Our collections turn a familiar route into an invitation to explore. From Paris to Kyoto, each medal is a keepsake of the effort you put in.</p><p>Walk it. Run it. Make it yours.</p>${link('/events','Explore the collection','dark')}<p><a class="text-link" href="${esc(site.instagram)}" target="_blank" rel="noreferrer">Follow @riserun.tt ↗</a></p></div><div class="editorial-photo">${img('/assets/travel-series.webp','The Rise & Run TT Travel the World collection')}</div></div></section>`,'Our story');}

function adminShell(content,title,action=''){
 document.title=title+' · Rise & Run admin';
 const tabs=[['/admin','grid','Overview'],['/admin/events','calendar','Events'],['/admin/participants','users','Participants'],['/admin/submissions','check','Review queue'],['/admin/users','users','Users'],['/admin/content','image','Site content'],['/admin/results','medal','Results'],['/admin/analytics','grid','Analytics'],['/admin/settings','settings','Settings']];
 $('#app').innerHTML=header(true)+`<div class="admin-shell"><aside class="admin-side"><span class="kicker">Race operations</span>${tabs.map(([p,i,t])=>`<a class="${route===p||(p!=='/admin'&&route.startsWith(p+'/'))?'active':''}" href="${p}">${icon(i)}${t}</a>`).join('')}<p class="local-note">Local workspace<br>Changes are saved on this computer.<br>Login is not enabled.</p></aside><main class="admin-main" id="main"><div class="admin-title"><div><span class="kicker">Rise & Run TT · Admin</span><h1>${title}</h1></div>${action}</div>${content}</main></div>`;menu();
}
const nameFor=id=>adminState.events.find(e=>e.id===id)?.name||id;
function adminOverview(){const {submissions:s,events:ev,participants:p}=adminState,pending=s.filter(x=>x.status==='pending'),approved=s.filter(x=>x.status==='approved');adminShell(`<div class="stat-grid">${stat('Open events',ev.filter(e=>e.status==='open').length)}${stat('Participants on rosters',p.filter(x=>x.active).length)}${stat('Awaiting review',pending.length)}${stat('Verified results',approved.length)}</div><div class="admin-panels"><section class="panel"><div class="section-heading"><h3>Your review queue</h3><a class="text-link" href="/admin/submissions">See all ↗</a></div>${pending.length?submissionTable(pending.slice(0,5)):empty('All caught up.','New participant submissions will appear here for review.')}</section><section class="panel"><span class="kicker">Your event collection</span><h3>Keep the next finish moving.</h3>${ev.map(e=>`<a class="mini-event" href="/admin/events/${e.id}" style="margin-top:20px">${img(e.cover,e.name+' medal')}<div><h4>${esc(e.name)}</h4><p>${badge(e.status)}</p></div></a>`).join('')}</section></div><div class="notice mt">The admin workspace is available locally without login. Participant uploads and event edits persist in the local database.</div>`,'Your race headquarters',link('/admin/events/new','Create event','dark'));}
function submissionTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Runner</th><th>Event / method</th><th>Activity</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${esc(s.displayName)}</strong><small>${esc(s.bib?'Bib '+s.bib:s.email)}</small></td><td>${esc(nameFor(s.eventId))}<small>${esc(s.method)}</small></td><td>${s.distance} km · ${time(s.seconds)}<small>${fmtDate(s.activityDate)}</small></td><td>${badge(s.status)}${s.flags.length?'<small>⚑ '+s.flags.length+' review flag(s)</small>':''}</td><td><a class="table-link" href="/admin/submissions/${s.id}">Review ↗</a></td></tr>`).join('')}</tbody></table></div>`;}
function adminEvents(){adminShell(`<div class="toolbar"><div class="search">${icon('search')}<input id="admin-event-search" type="search" aria-label="Search managed events" placeholder="Find an event"></div><select id="admin-event-filter" aria-label="Event status"><option value="all">All statuses</option>${['open','draft','closed','completed'].map(x=>`<option>${x}</option>`).join('')}</select></div><div id="admin-events-list"></div>`,'Manage your events',link('/admin/events/new','Create event','dark'));const render=()=>{const q=$('#admin-event-search').value.toLowerCase(),f=$('#admin-event-filter').value,rows=adminState.events.filter(e=>e.name.toLowerCase().includes(q)&&(f==='all'||e.status===f));$('#admin-events-list').innerHTML=rows.length?`<div class="run-list">${rows.map(e=>`<article class="run-card">${img(e.cover,e.name+' medal')}<div>${badge(e.status)}<h3>${esc(e.name)}</h3><p>${e.distance} km · ${e.activities.map(esc).join(' / ')} · ${fmtDate(e.startDate)}</p></div><div class="actions">${e.status!=='draft'?link(ep(e),'View','outline compact'):''}${link('/admin/events/'+e.id,'Edit event','dark compact')}</div></article>`).join('')}</div>`:empty('No events match.','Try another search, or create an event.');};$('#admin-event-search').oninput=render;$('#admin-event-filter').onchange=render;render();}
async function eventEditor(id){const isNew=id==='new',original=isNew?null:adminState.events.find(x=>x.id===id);if(!isNew&&!original)throw new Error('Event not found.');let e=original?structuredClone(original):{name:'',subtitle:'',series:'',location:'',description:'',medalDescription:'',distance:5,minDistance:5,maxDistance:5.5,activities:['Run','Walk'],status:'draft',startDate:'',endDate:'',deadline:'',collection:'',pickupLocations:[],methods:['screenshot','strava'],allowLate:false,allowResubmit:true,requireEnrollment:false,homeFeatured:false,homePosition:99,gallery:[],cover:'',medal:''};
 adminShell(`<form id="event-editor" class="admin-form"><div class="panel"><span class="kicker">01 · The essentials</span><h3>Tell the event’s story.</h3><div class="form-grid">${field('Event name','name','text',e.name,'required maxlength="100"')}${field('URL slug','slug','text',e.id||'','pattern="[a-z0-9-]+" '+(!isNew?'readonly':''))}${field('Subtitle','subtitle','text',e.subtitle)}${field('Collection / series','series','text',e.series)}${field('Destination / location','location','text',e.location)}<div><label for="status">Publishing status</label><select name="status" id="status">${['draft','open','closed','completed'].map(s=>`<option ${e.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="span-2"><label for="description">Event description</label><textarea id="description" name="description" required maxlength="6000">${esc(e.description)}</textarea></div><div class="span-2"><label for="medalDescription">Medal description</label><textarea id="medalDescription" name="medalDescription">${esc(e.medalDescription)}</textarea></div></div></div><div class="panel"><span class="kicker">02 · The visual experience</span><h3>Give the event its identity.</h3><p class="muted mb">Portrait artwork works best at 4:5. Use a clear medal image with room around its edges.</p><div class="form-grid">${['cover','medal'].map(k=>`<div><label for="${k}-upload">${k==='cover'?'Cover artwork':'Medal image'}</label><div class="media-edit"><div id="${k}-preview">${img(e[k],k+' preview')}</div><input type="file" id="${k}-upload" accept="image/png,image/jpeg,image/webp" data-media="${k}"></div></div>`).join('')}<div class="span-2"><label for="gallery-upload">Gallery images</label><input type="file" id="gallery-upload" multiple accept="image/png,image/jpeg,image/webp"><div class="gallery-edit" id="gallery-editor"></div></div></div></div><div class="panel"><span class="kicker">03 · The run</span><h3>Distance, dates and collection.</h3><div class="form-grid">${field('Required distance (km)','distance','number',e.distance,'required min="0.1" max="1000" step="0.01"')}${field('Minimum accepted distance (km)','minDistance','number',e.minDistance,'required min="0.1" step="0.01"')}${field('Maximum accepted distance (km)','maxDistance','number',e.maxDistance,'required min="0.1" step="0.01"')}${field('Activity window opens','startDate','date',e.startDate)}${field('Activity window closes','endDate','date',e.endDate)}${field('Submission deadline','deadline','date',e.deadline)}${field('Medal collection details','collection','text',e.collection)}<div><label for="pickupLocations">Pickup locations (one per line)</label><textarea id="pickupLocations" name="pickupLocations">${e.pickupLocations.map(esc).join('\n')}</textarea></div></div><p class="field-help mt">Blank dates leave the activity window flexible. All date boundaries use Trinidad & Tobago time.</p></div><div class="panel"><span class="kicker">04 · Verification rules</span><h3>How runners make it official.</h3><label>Allowed activities</label><div class="check-group mb">${['Run','Walk','Cycle','Swim'].map(a=>`<label class="check"><input type="checkbox" name="activities" value="${a}" ${e.activities.includes(a)?'checked':''}>${a}</label>`).join('')}</div><label>Submission methods</label><div class="check-group mb">${[['screenshot','Screenshot upload'],['strava','Strava activity link']].map(([v,t])=>`<label class="check"><input type="checkbox" name="methods" value="${v}" ${e.methods.includes(v)?'checked':''}>${t}</label>`).join('')}</div>${[['allowResubmit','Allow resubmission after rejection'],['allowLate','Allow late submissions after the deadline'],['requireEnrollment','Only accept emails on the event participant roster']].map(([k,t])=>`<label class="check"><input type="checkbox" name="${k}" ${e[k]?'checked':''}>${t}</label>`).join('')}</div><div class="form-error" role="alert"></div><div class="admin-actions"><button class="button dark" type="submit">${isNew?'Create event':'Save event changes'} ↗</button>${link('/admin/events','Back to events','outline')}${!isNew&&e.status==='draft'?'<button class="button danger" type="button" id="delete-draft">Delete draft</button>':''}</div></form>`,isNew?'Create a new event':'Edit '+esc(e.name));
 const form=$('#event-editor'),essentials=$('.panel .form-grid',form);essentials.insertAdjacentHTML('beforeend',`<div class="span-2 home-feature-control"><label class="check"><input type="checkbox" name="homeFeatured" ${e.homeFeatured?'checked':''}>Feature this event on the homepage</label><label>Homepage position <input name="homePosition" type="number" min="1" max="99" value="${Number(e.homePosition||99)}"></label><p class="field-help">Featured events appear first. Position 1 is the homepage hero; then 2 and 3 fill the featured event cards.</p></div>`);if(isNew)$('#name').addEventListener('input',()=>{if(!$('#slug').dataset.manual)$('#slug').value=$('#name').value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');});$('#slug').oninput=()=>$('#slug').dataset.manual='true';
 const gallery=()=>{$('#gallery-editor').innerHTML=e.gallery.map((src,i)=>`<div class="item">${img(src,'Gallery image '+(i+1))}<button type="button" data-remove="${i}" aria-label="Remove gallery image ${i+1}">×</button></div>`).join('');$$('[data-remove]').forEach(b=>b.onclick=()=>{e.gallery.splice(Number(b.dataset.remove),1);gallery();});};gallery();
 let uploads=0;async function upload(f){uploads++;try{return (await api('/admin/media','POST',{image:await getImage(f)})).url;}finally{uploads--;}}
 $$('[data-media]').forEach(input=>input.onchange=async()=>{if(!input.files[0])return;try{e[input.dataset.media]=await upload(input.files[0]);$('#'+input.dataset.media+'-preview').innerHTML=img(e[input.dataset.media],input.dataset.media+' preview');toast('Image saved.');}catch(err){formError(form,err);}});
 $('#gallery-upload').onchange=async x=>{try{for(const f of x.target.files)e.gallery.push(await upload(f));gallery();}catch(err){formError(form,err);}};
 form.onsubmit=async x=>{x.preventDefault();const b=$('button[type=submit]',form);b.disabled=true;try{if(uploads)throw new Error('Wait for the image uploads to finish.');const f=new FormData(form),payload={...e,...Object.fromEntries(f),activities:f.getAll('activities'),methods:f.getAll('methods'),pickupLocations:String(f.get('pickupLocations')).split('\n').map(s=>s.trim()).filter(Boolean)};for(const k of ['allowLate','allowResubmit','requireEnrollment','homeFeatured'])payload[k]=f.has(k);const saved=await api('/admin/events'+(isNew?'':'/'+e.id),isNew?'POST':'PUT',payload);location.href='/admin/events/'+saved.id+'?saved=1';}catch(err){formError(form,err);b.disabled=false;}};
 $('#delete-draft')?.addEventListener('click',async()=>{if(!confirm('Permanently delete this event, its participant list and all submissions? This cannot be undone.'))return;try{await api('/admin/events/'+e.id,'DELETE');location.href='/admin/events';}catch(err){formError(form,err);}});
 $('#delete-draft')?.remove();if(!isNew){const totals={participants:adminState.participants.filter(x=>x.eventId===e.id).length,submissions:adminState.submissions.filter(x=>x.eventId===e.id).length};$('.admin-actions',form).insertAdjacentHTML('beforeend',`<button class="button danger" type="button" id="delete-event">Delete event permanently</button><small class="delete-help">Also removes ${totals.participants} participant${totals.participants===1?'':'s'} and ${totals.submissions} submission${totals.submissions===1?'':'s'}.</small>`);$('#delete-event').onclick=async()=>{if(!confirm(`Permanently delete “${e.name}”, its participant list and all submissions? This cannot be undone.`))return;try{await api('/admin/events/'+e.id,'DELETE');location.href='/admin/events';}catch(error){formError(form,error);}};}if(new URLSearchParams(location.search).has('saved'))toast('Event saved.');
}
function adminSubmissions(resultsOnly=false){const rows=adminState.submissions.filter(s=>!resultsOnly||s.status==='approved');adminShell(`<div class="toolbar"><div class="search">${icon('search')}<input id="submission-search" type="search" aria-label="Search submissions" placeholder="Search runner, email or bib"></div><select id="event-filter" aria-label="Filter by event"><option value="all">All events</option>${adminState.events.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select>${resultsOnly?'':`<select id="review-filter" aria-label="Review status"><option value="all">All statuses</option><option value="pending" selected>Awaiting review</option><option value="approved">Approved</option><option value="rejected">Needs attention</option><option value="flagged">Flagged</option></select>`}<button class="button outline compact" id="export-admin">Export CSV</button></div><div id="submission-list"></div>`,resultsOnly?'Manage official results':'Review submissions');const filtered=()=>{const q=$('#submission-search').value.toLowerCase(),event=$('#event-filter').value,f=$('#review-filter')?.value||'all';return rows.filter(s=>[s.displayName,s.email,s.bib].join(' ').toLowerCase().includes(q)&&(event==='all'||s.eventId===event)&&(f==='all'||(f==='flagged'?s.flags.length:s.status===f)));};const render=()=>{const list=filtered().reverse();$('#submission-list').innerHTML=list.length?submissionTable(list):empty(resultsOnly?'No verified results yet.':'No submissions to review.','Results and review queues fill automatically when runners submit their activities.');};$('#submission-search').oninput=render;$('#event-filter').onchange=render;if($('#review-filter'))$('#review-filter').onchange=render;$('#export-admin').onclick=()=>downloadCSV('run-submissions',[['Runner','Event','Method','Distance','Time','Status','Activity date'],...filtered().map(s=>[s.displayName,nameFor(s.eventId),s.method,s.distance,time(s.seconds),s.status,s.activityDate])]);render();}
function reviewPage(id){const s=adminState.submissions.find(x=>x.id===id),e=adminState.events.find(x=>x.id===s?.eventId);if(!s)throw new Error('Submission not found.');adminShell(`<div class="breadcrumbs"><a href="/admin/submissions">Submissions</a><span>/</span><span>${esc(s.displayName)}</span></div><div class="review-layout"><section class="panel"><h3>Activity evidence</h3>${s.method==='screenshot'?`<a href="/api/admin/evidence/${s.id}" target="_blank" rel="noreferrer"><img class="evidence-image" src="/api/admin/evidence/${s.id}" alt="Run screenshot submitted by ${esc(s.displayName)}"></a><p class="field-help mt">Click the screenshot to inspect it at full size.</p>`:`<div class="notice info">The runner supplied a Strava activity link. Check ownership, date, time and distance before approval.</div><a class="button dark" href="${esc(s.stravaUrl)}" target="_blank" rel="noreferrer">Open Strava activity ↗</a><p class="small mt">${esc(s.stravaUrl)}</p>`}${s.notes?`<h4 class="mt">Runner’s note</h4><p class="muted mt">${esc(s.notes)}</p>`:''}</section><section class="panel"><div class="section-heading"><h3>${esc(s.displayName)}</h3>${badge(s.status)}</div><p class="small">${esc(e?.name)}<br>${esc(s.email)}</p><div class="review-data">${[['Distance',s.distance+' km'],['Time',time(s.seconds)],['Pace',pace(s.seconds,s.distance)],['Activity date',fmtDate(s.activityDate)],['Activity type',s.activity],['Bib',s.bib||'Not assigned']].map(([l,v])=>`<div><small>${l}</small><strong>${esc(v)}</strong></div>`).join('')}</div>${s.flags.map(f=>`<div class="notice">⚑ ${esc(f)}</div>`).join('')}<form id="review-form"><div class="form-section"><h4>Correct activity details if needed</h4><div class="form-grid">${field('Distance (km)','review-distance','number',s.distance,`step="0.01" min="${e.minDistance}" max="${e.maxDistance}" required`)}${field('Completion time','review-time','text',time(s.seconds),'required')}</div></div><div class="mt"><label for="review-reason">Reason / guidance for the runner</label><textarea id="review-reason" maxlength="1000">${esc(s.reason)}</textarea><p class="field-help">A reason is required when a run needs resubmission.</p></div><div class="form-error" role="alert"></div><div class="actions mt"><button type="submit" class="button dark" value="approved">${s.status==='approved'?'Save approved result':'Approve run'}</button><button type="submit" class="button danger" value="rejected">Request resubmission</button><button type="submit" class="button outline compact" value="pending">Return to pending</button></div></form></section></div>`,'Review the finish');$('#review-form').onsubmit=async ev=>{ev.preventDefault();const status=ev.submitter.value,form=ev.currentTarget;try{const seconds=parseTime($('#review-time').value);if(!Number.isFinite(seconds))throw new Error('Enter a valid time.');if(status==='rejected'&&!$('#review-reason').value.trim())throw new Error('Add a reason so the runner knows what to correct.');await api('/admin/submissions/'+s.id,'PATCH',{status,reason:$('#review-reason').value,seconds,distance:Number($('#review-distance').value)});location.href='/admin/submissions?reviewed=1';}catch(err){formError(form,err);}};}
function parseCSV(input){let rows=[],row=[],value='',quoted=false;for(let i=0;i<input.length;i++){const c=input[i];if(c==='"'){if(quoted&&input[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(value);value='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&input[i+1]==='\n')i++;row.push(value);if(row.some(v=>v.trim()))rows.push(row);row=[];value='';}else value+=c;}if(quoted)throw new Error('CSV has an unclosed quotation mark.');row.push(value);if(row.some(v=>v.trim()))rows.push(row);return rows;}
function adminParticipants(){adminShell(`<div class="admin-panels"><section class="panel"><h3>Add an existing participant</h3><form id="participant-form"><input type="hidden" name="id" id="participant-id"><div class="form-grid">${field('Participant name','name','text','','required')}${field('Email','email','email','','required')}<div><label for="eventId">Event</label><select id="eventId" name="eventId" required>${adminState.events.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></div>${field('Bib number','bib')}${field('Country','country','text','Trinidad & Tobago')}<label class="check" style="align-self:center"><input type="checkbox" name="active" id="active" checked>Active participant</label></div><div class="form-error" role="alert"></div><div class="actions mt"><button class="button dark">Save participant</button><button type="button" class="button outline" id="clear-participant">Clear form</button></div></form></section><section class="panel"><span class="kicker">Bring your roster</span><h3>Import participants</h3><p class="small muted">Upload a CSV with Name, Email, Event, Bib Number and Country. Event accepts the event name or URL slug.</p><button class="text-link mt" style="background:none;border-width:0 0 1px" id="csv-template">Download CSV template ↗</button><label for="csv-upload" class="mt">Participant CSV</label><input type="file" id="csv-upload" accept=".csv,text/csv"><div id="import-preview" class="small mt"></div><button class="button dark mt" id="confirm-import" disabled>Import validated rows</button><div id="import-error" class="form-error" role="alert"></div></section></div><div class="toolbar mt"><div class="search">${icon('search')}<input id="participant-search" type="search" aria-label="Search participants" placeholder="Search name, email or bib"></div><button class="button outline compact" id="export-participants">Export roster</button></div><div id="participant-table"></div>`,'Participant rosters');
 const render=()=>{const q=$('#participant-search').value.toLowerCase(),rows=adminState.participants.filter(p=>[p.name,p.email,p.bib].join(' ').toLowerCase().includes(q));$('#participant-table').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Participant</th><th>Event</th><th>Bib</th><th>State</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.name)}<small>${esc(p.email)}</small></td><td>${esc(nameFor(p.eventId))}</td><td>${esc(p.bib||'—')}</td><td>${p.active?'Active':'Inactive'}</td><td><button class="button outline compact" data-edit-person="${p.id}">Edit / history</button></td></tr>`).join('')}</tbody></table></div>`:empty('No participants on this roster.','Add participants to the event roster, or import your existing CSV.');$$('[data-edit-person]').forEach(b=>b.onclick=()=>{const p=adminState.participants.find(x=>x.id===b.dataset.editPerson),f=$('#participant-form');for(const k of ['name','email','eventId','bib','country'])f.elements[k].value=p[k];$('#participant-id').value=p.id;$('#active').checked=p.active;const history=adminState.submissions.filter(s=>s.email===p.email);let h=$('#participant-history');if(!h){h=document.createElement('div');h.id='participant-history';h.className='mt';f.append(h);}h.innerHTML='<h4 class="mb">Submission history</h4>'+(history.length?submissionTable(history):'<p class="small muted">No submissions for this participant.</p>');f.scrollIntoView({block:'center'});});};render();$('#participant-search').oninput=render;
 $('#participant-form').onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget,x=Object.fromEntries(new FormData(f));x.active=$('#active').checked;if(!x.id)delete x.id;try{await api('/admin/participants'+(x.id?'/'+x.id:''),x.id?'PUT':'POST',x);location.reload();}catch(err){formError(f,err);}};$('#clear-participant').onclick=()=>{$('#participant-form').reset();$('#participant-id').value='';$('#participant-history')?.remove();};
 $('#csv-template').onclick=()=>downloadCSV('participant-template',[['Name','Email','Event','Bib Number','Country']]);$('#export-participants').onclick=()=>downloadCSV('participants',[['Name','Email','Event','Bib Number','Country','Active'],...adminState.participants.map(p=>[p.name,p.email,p.eventId,p.bib,p.country,p.active])]);let rows=[];
 $('#csv-upload').onchange=async ev=>{rows=[];$('#confirm-import').disabled=true;$('#import-error').textContent='';try{const f=ev.target.files[0];if(!f)return;if(f.size>2*1024*1024)throw new Error('CSV must be smaller than 2 MB.');const data=parseCSV(await f.text());if(data.length<2)throw new Error('Add at least one participant row.');const head=data.shift().map(x=>x.replace(/^\uFEFF/,'').trim().toLowerCase().replace(/[ _-]/g,''));const get=(r,...names)=>{const i=head.findIndex(h=>names.includes(h));return i<0?'':(r[i]||'').trim();};const seen=new Set();rows=data.map((r,i)=>{const event=get(r,'event','eventid'),e=adminState.events.find(e=>e.id===event||e.name.toLowerCase()===event.toLowerCase());const name=get(r,'name')||[get(r,'firstname'),get(r,'lastname')].filter(Boolean).join(' ');const email=get(r,'email').toLowerCase();if(!e||!name||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw new Error('Row '+(i+2)+': check participant name, email and event.');const key=e.id+':'+email;if(seen.has(key)||adminState.participants.some(p=>p.eventId===e.id&&p.email===email))throw new Error('Row '+(i+2)+': duplicate participant.');seen.add(key);return {name,email,eventId:e.id,bib:get(r,'bibnumber','bib'),country:get(r,'country')||'Trinidad & Tobago'};});$('#import-preview').textContent=`${rows.length} valid participants ready to import. First: ${rows.slice(0,3).map(r=>r.name).join(', ')}.`;$('#confirm-import').disabled=false;}catch(err){rows=[];$('#import-error').textContent=err.message;}};$('#confirm-import').onclick=async()=>{try{const r=await api('/admin/import','POST',{rows});toast(r.count+' participants imported.');setTimeout(()=>location.reload(),700);}catch(err){$('#import-error').textContent=err.message;}};
}
function adminAnalytics(){const s=adminState.submissions,approved=s.filter(x=>x.status==='approved'),reviewed=s.filter(x=>x.status!=='pending');const times=approved.map(x=>x.seconds).sort((a,b)=>a-b),avg=times.length?times.reduce((a,b)=>a+b,0)/times.length:0,mid=Math.floor(times.length/2),median=times.length?(times.length%2?times[mid]:(times[mid-1]+times[mid])/2):0;adminShell(`<div class="stat-grid">${stat('Approval rate',reviewed.length?Math.round(approved.length/reviewed.length*100)+'%':'—')}${stat('Average finish',times.length?time(avg):'—')}${stat('Median finish',times.length?time(median):'—')}${stat('Total verified distance',approved.reduce((sum,x)=>sum+x.distance,0).toFixed(2)+' km')}</div><div class="admin-panels"><section class="panel"><h3>Event participation</h3><div class="table-wrap"><table><thead><tr><th>Event</th><th>Roster</th><th>Submissions</th><th>Finishers</th></tr></thead><tbody>${adminState.events.map(e=>`<tr><td>${esc(e.name)}</td><td>${adminState.participants.filter(p=>p.eventId===e.id&&p.active).length}</td><td>${s.filter(x=>x.eventId===e.id).length}</td><td>${approved.filter(x=>x.eventId===e.id).length}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h3>How runners submit</h3>${['screenshot','strava'].map(method=>{const n=s.filter(x=>x.method===method).length;return `<div class="bar-row"><span>${method==='strava'?'Strava link':'Screenshot'}</span><div class="bar-track"><span style="width:${s.length?n/s.length*100:0}%"></span></div><b>${n}</b></div>`;}).join('')}<p class="small muted mt">Calculated from stored submissions. No estimated or sample figures.</p></section></div>`,'Understand your events');}
function adminSettings(){const s=adminState.settings;adminShell(`<form class="panel" id="settings-form" style="max-width:800px"><h3>Your organizer details</h3><div class="form-grid">${field('Organization name','name','text',s.name,'required')}${field('Tagline','tagline','text',s.tagline)}${field('Contact email','email','email',s.email,'required')}${field('Contact phone','phone','text',s.phone)}${field('Instagram profile URL','instagram','url',s.instagram,'required')}${field('Maximum image upload (MB)','maxUploadMB','number',s.maxUploadMB,'required min="1" max="20"')}</div><div class="notice mt">This build runs locally with account login and external email delivery disabled. Event changes, uploads and reviews are saved on this computer.</div><div class="form-error" role="alert"></div><button class="button dark mt">Save settings</button></form>`,'Workspace settings');$('#settings-form').onsubmit=async ev=>{ev.preventDefault();try{site=await api('/admin/settings','PUT',Object.fromEntries(new FormData(ev.currentTarget)));toast('Workspace settings saved.');}catch(err){formError(ev.currentTarget,err);}};}
function adminUsers(){const users=adminState.users||[],runs=adminState.submissions||[];adminShell(`<div class="stat-grid">${stat('Registered runners',users.length)}${stat('Verified emails',users.filter(u=>u.emailVerified).length)}${stat('Unverified emails',users.filter(u=>!u.emailVerified).length)}${stat('Runners with a submission',new Set(runs.map(s=>s.profileId)).size)}</div><div class="toolbar mt"><div class="search">${icon('search')}<input id="user-search" type="search" aria-label="Search users" placeholder="Search name or email"></div></div><div id="user-table" class="mt"></div><div id="user-detail" class="panel mt" hidden></div>`,'Registered runners');const render=()=>{const q=$('#user-search').value.toLowerCase(),rows=users.filter(u=>[u.name,u.displayName,u.email].join(' ').toLowerCase().includes(q));$('#user-table').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Runner</th><th>Account status</th><th>Joined</th><th>Submissions</th><th></th></tr></thead><tbody>${rows.map(u=>{const total=runs.filter(s=>s.profileId===u.id),approved=total.filter(s=>s.status==='approved').length;return `<tr><td><strong>${esc(u.displayName||u.name)}</strong><small>${esc(u.email)}</small></td><td>${u.emailVerified?'<span class="badge approved">Email verified</span>':'<span class="badge pending">Verification pending</span>'}</td><td>${u.createdAt?fmtDate(u.createdAt.slice(0,10)):'—'}</td><td>${total.length}<small>${approved} approved</small></td><td><button class="button outline compact" data-user="${u.id}">View</button></td></tr>`;}).join('')}</tbody></table></div>`:empty('No matching users.','Try another name or email address.');$$('[data-user]').forEach(button=>button.onclick=()=>{const u=users.find(x=>x.id===button.dataset.user),history=runs.filter(s=>s.profileId===u.id),detail=$('#user-detail');detail.hidden=false;detail.innerHTML=`<div class="section-heading"><div><span class="kicker">Runner account</span><h3>${esc(u.displayName||u.name)}</h3><p class="small muted">${esc(u.email)}</p></div><button class="button outline compact" id="toggle-verified">${u.emailVerified?'Mark unverified':'Mark email verified'}</button></div><p class="small">Joined ${u.createdAt?fmtDate(u.createdAt.slice(0,10)):'—'} · ${history.length} submission${history.length===1?'':'s'}.</p>${history.length?submissionTable(history):'<p class="small muted">This runner has not submitted an activity yet.</p>'}`;$('#toggle-verified').onclick=async()=>{try{await api('/admin/users/'+u.id,'PATCH',{emailVerified:!u.emailVerified});location.reload();}catch(err){toast(err.message);}};detail.scrollIntoView({behavior:'smooth',block:'start'});});};render();$('#user-search').oninput=render;}
const originalHomepage=home;home=()=>{const ordered=[...events].sort((a,b)=>Number(Boolean(b.homeFeatured))-Number(Boolean(a.homeFeatured))||Number(a.homePosition||99)-Number(b.homePosition||99)||a.name.localeCompare(b.name)),savedEvents=events;events=ordered;originalHomepage();events=savedEvents;const featured=ordered[0],heroImage=$('.hero-art>img'),heroLink=$('.hero-caption a'),heroTitle=$('.hero-caption b'),heroMeta=$('.hero-caption small');if(featured&&heroImage){heroImage.src=featured.cover||artSource;heroImage.alt=featured.name+' campaign medal';heroLink.href=ep(featured);heroTitle.textContent=featured.name;heroMeta.textContent=(featured.series||'Rise & Run TT')+' · '+(featured.location||'Run anywhere');}};
const originalHome=home;home=()=>{originalHome();const editorial=$('.editorial-photo>img'),story=$('.story-band img');if(site.homeEditorialImage&&editorial)editorial.src=site.homeEditorialImage;if(site.homeStoryImage&&story)story.src=site.homeStoryImage;const editorialHeading=$('.editorial h2'),editorialCopy=$('.editorial h2')?.parentElement?.querySelector('p'),storyHeading=$('.story-band h2'),storyCopy=$('.story-band .copy p');if(site.homeEditorialHeading&&editorialHeading)editorialHeading.textContent=site.homeEditorialHeading;if(site.homeEditorialCopy&&editorialCopy)editorialCopy.textContent=site.homeEditorialCopy;if(site.homeStoryHeading&&storyHeading)storyHeading.textContent=site.homeStoryHeading;if(site.homeStoryCopy&&storyCopy)storyCopy.textContent=site.homeStoryCopy;};
adminContent=function(){const s=adminState.settings;adminShell(`<form class="admin-form" id="content-form"><div class="panel"><span class="kicker">Homepage visuals</span><h3>Replace your featured images.</h3><p class="small muted mb">For the best fit, use a clear landscape or square image. It will be shown fully without cropping.</p><div class="form-grid"><div><label>Paris / editorial image</label><div class="media-edit"><div id="homeEditorialImage-preview">${img(s.homeEditorialImage||'/assets/paris-campaign.webp','Editorial preview')}</div><input type="file" id="homeEditorialImage-upload" accept="image/png,image/jpeg,image/webp"></div></div><div><label>Kyoto / story image</label><div class="media-edit"><div id="homeStoryImage-preview">${img(s.homeStoryImage||'/assets/kyoto-postcard.webp','Story preview')}</div><input type="file" id="homeStoryImage-upload" accept="image/png,image/jpeg,image/webp"></div></div></div></div><div class="panel"><span class="kicker">Homepage copy</span><h3>Edit the two feature sections.</h3><div class="form-grid"><div class="span-2">${field('Editorial heading','homeEditorialHeading','text',s.homeEditorialHeading||'')}</div><div class="span-2"><label>Editorial paragraph</label><textarea name="homeEditorialCopy" maxlength="2000">${esc(s.homeEditorialCopy||'')}</textarea></div><div class="span-2">${field('Story heading','homeStoryHeading','text',s.homeStoryHeading||'')}</div><div class="span-2"><label>Story paragraph</label><textarea name="homeStoryCopy" maxlength="2000">${esc(s.homeStoryCopy||'')}</textarea></div></div></div><div class="form-error" role="alert"></div><button class="button dark" type="submit">Publish home-page changes ↗</button></form>`,'Site content');let uploads=0;const upload=async file=>{uploads++;try{return (await api('/admin/media','POST',{image:await getImage(file)})).url;}finally{uploads--;}};for(const key of ['homeEditorialImage','homeStoryImage'])$('#'+key+'-upload').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{s[key]=await upload(file);$('#'+key+'-preview').innerHTML=img(s[key],key+' preview');toast('Image uploaded. Publish changes when ready.');}catch(error){formError($('#content-form'),error);}};$('#content-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;try{if(uploads)throw new Error('Wait for the image upload to finish.');site=await api('/admin/settings','PUT',{...s,...Object.fromEntries(new FormData(form)),homeEditorialImage:s.homeEditorialImage||'',homeStoryImage:s.homeStoryImage||''});toast('Homepage changes published.');}catch(error){formError(form,error);}};};
adminUsers=function(){const users=adminState.users||[],runs=adminState.submissions||[];adminShell(`<div class="stat-grid">${stat('Registered runners',users.length)}${stat('Runners with a submission',new Set(runs.map(s=>s.profileId)).size)}${stat('Verified finishes',runs.filter(s=>s.status==='approved').length)}${stat('Pending reviews',runs.filter(s=>s.status==='pending').length)}</div><div class="toolbar mt"><div class="search">${icon('search')}<input id="user-search" type="search" aria-label="Search users" placeholder="Search name or email"></div></div><div id="user-table" class="mt"></div><div id="user-detail" class="panel mt" hidden></div>`,'Registered runners');const render=()=>{const q=$('#user-search').value.toLowerCase(),rows=users.filter(u=>[u.name,u.displayName,u.email].join(' ').toLowerCase().includes(q));$('#user-table').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Runner</th><th>Joined</th><th>Submissions</th><th>Approved</th><th></th></tr></thead><tbody>${rows.map(u=>{const history=runs.filter(s=>s.profileId===u.id);return `<tr><td><strong>${esc(u.displayName||u.name)}</strong><small>${esc(u.email)}</small></td><td>${u.createdAt?fmtDate(u.createdAt.slice(0,10)):'—'}</td><td>${history.length}</td><td>${history.filter(s=>s.status==='approved').length}</td><td><button class="button outline compact" data-user="${u.id}">View history</button></td></tr>`;}).join('')}</tbody></table></div>`:empty('No matching users.','Try another name or email address.');$$('[data-user]').forEach(button=>button.onclick=()=>{const u=users.find(x=>x.id===button.dataset.user),history=runs.filter(s=>s.profileId===u.id),detail=$('#user-detail');detail.hidden=false;detail.innerHTML=`<span class="kicker">Runner account</span><h3>${esc(u.displayName||u.name)}</h3><p class="small muted">${esc(u.email)} · Joined ${u.createdAt?fmtDate(u.createdAt.slice(0,10)):'—'}</p>${history.length?submissionTable(history):'<p class="small muted">This runner has not submitted an activity yet.</p>'}`;detail.scrollIntoView({behavior:'smooth',block:'start'});});};render();$('#user-search').oninput=render;};
async function main(){
 [site,events]=await Promise.all([api('/site'),api('/events')]);
 if(route==='/'||route==='/RISENRUNTT_website.html')return home();
 if(route==='/events')return catalogue();if(route==='/results')return catalogue(true);
 if(route==='/my-runs')return myRuns();if(route.startsWith('/my-runs/'))return runStatus(route.split('/')[2]);
 if(route==='/profile')return profilePage();if(route==='/how-it-works')return howPage();if(route==='/faq')return faqPage();if(route==='/about')return aboutPage();
 if(route.startsWith('/results/'))return resultPage(route.split('/')[2]);
 if(route.startsWith('/events/')){const [,,id,action]=route.split('/'),e=events.find(e=>e.id===id);if(!e)throw new Error('This event is unavailable or is not published yet.');if(action==='submit')return submitPage(e);if(action==='results')return leaderboard(e);if(!action)return eventDetail(e);}
 if(route.startsWith('/admin')){adminState=await api('/admin/state');if(route==='/admin')return adminOverview();if(route==='/admin/events')return adminEvents();if(route.startsWith('/admin/events/'))return eventEditor(route.split('/')[3]);if(route==='/admin/submissions')return adminSubmissions();if(route.startsWith('/admin/submissions/'))return reviewPage(route.split('/')[3]);if(route==='/admin/participants')return adminParticipants();if(route==='/admin/users')return adminUsers();if(route==='/admin/content')return adminContent();if(route==='/admin/results')return adminSubmissions(true);if(route==='/admin/analytics')return adminAnalytics();if(route==='/admin/settings')return adminSettings();}
 throw new Error('We couldn’t find that page.');
}
const standardAdminContent=adminContent;adminContent=()=>{standardAdminContent();for(const key of ['homeEditorialImage','homeStoryImage']){const preview=$('#'+key+'-preview'),picker=$('#'+key+'-upload');preview.setAttribute('role','button');preview.setAttribute('tabindex','0');preview.setAttribute('aria-label','Choose a new image');preview.title='Click to choose a new image';preview.onclick=()=>picker.click();preview.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();picker.click();}};}};
main().catch(err=>{console.error(err);if(site)shell(`<section class="section"><div class="container">${empty('Let’s get you back on track.',esc(err.message),'/events')}</div></section>`,'Page unavailable');else $('#app').innerHTML='<div class="loading">Unable to load the site. Please check the local server and refresh.</div>';});
